// Builds the South African Politics curriculum.
//
// Source: scripts/curriculums/sa-politics.md, which is the plan and the
// argument. The material is in sa-politics-detail.json and the cards are in
// sa-politics-cards.json, for the reasons japanese.mjs gives: prose full of
// tables does not belong inside a JS template literal, and cards are data
// rather than prose.
//
// A REWRITE, NOT A REVISION. The first version (2026-10-09) was 8 stages and
// 32 lessons with about 560 characters of material each -- the thinnest of the
// eight curriculums, and closer to an index than a course. Every lesson here
// teaches its point in full and then directs practice.
//
// HIS FOUR RULINGS, 2026-10-14:
//   1. Expand the structure as well as the material -- eight stages become
//      twelve, and the present gets stages of its own for the institutions,
//      the economy, and the parties and the press.
//   2. As long as it needs. No target; each stage is sized to its material.
//   3. A card deck, unlike Godot -- legislation, dates, institutions,
//      constitutional sections and the numbers that get argued about.
//   4. The present is written as structures and arguments, with any specific
//      result or office-holder in a DATED SNAPSHOT. The municipal elections
//      are on 4 November 2026 and this was written on 14 October.
//
// NOT TO ARRIVE AT A POSITION, which is his standing ruling for this subject
// and the reason stage 1 exists. Where a question is live the material gives
// the strongest form of each answer and says what evidence would settle it.
// The deck therefore avoids the contested parts: a card asserts.
//
// TWO CORRECTIONS TO THE FIRST VERSION, both in sa-politics.md: the library
// holds EIGHTEEN books on this subject rather than the five the first version
// named -- Simpson runs to 2021, so the claim that it held "nothing on the
// Mbeki years, state capture, the Zondo Commission or the present coalition"
// was false -- and one of the eighteen, `The Unauthorised History of South
// Africa`, is comedy and is excluded.
//
// Prints SQL. Nothing is executed here -- `npm run curriculum sa-politics`.

import detail from './sa-politics-detail.json' with { type: 'json' };
import cards from './sa-politics-cards.json' with { type: 'json' };

const SOURCE = 'scripts/curriculums/sa-politics.md';
const NAME = 'South African Politics';

/** SQL single-quoted string. An apostrophe in a title ends the literal early. */
const q = (value) =>
  value === null || value === undefined ? 'null' : `'${String(value).replace(/'/g, "''")}'`;

const NOW = new Date().toISOString();
const CURRICULUM = `(select id from curriculums where name = ${q(NAME)})`;
/** The lesson just inserted. The other scripts use the same trick. */
const LESSON = '(select max(id) from lessons)';

/** Every key asked for, so a stray one in a data file can be found. */
const askedDetail = new Set();
const askedCards = new Set();
const missing = [];

function detailFor(name) {
  askedDetail.add(name);
  const text = detail[name];
  if (text === undefined) {
    // Loud rather than silent: a lesson renamed here and not in the data file
    // would otherwise quietly lose its material.
    missing.push(name);
    return null;
  }
  return text;
}

/**
 * A card's natural key, which is what the database matches on: curriculum,
 * kind and front. Two lessons claiming the same one is a silent bug -- the
 * insert is `where not exists`, so the second claim does not fail, it just
 * quietly re-points the card at the later lesson. Caught here instead.
 */
const claimed = new Map();
const twiceClaimed = [];

function cardsFor(name) {
  askedCards.add(name);
  const list = cards[name] ?? [];
  for (const card of list) {
    const key = `${card.kind}\u0000${card.front}`;
    if (claimed.has(key)) twiceClaimed.push([card.front, claimed.get(key), name]);
    else claimed.set(key, name);
  }
  return list;
}

/**
 * A lesson is either a bare name or [name, sources]. Sources are per-lesson
 * rows in `sources`; the curriculum's OWN list (lesson_id is null) is
 * dashboard-owned and no script regenerates it.
 */
const nameOf = (lesson) => (Array.isArray(lesson) ? lesson[0] : lesson);
const sourcesOf = (lesson) => (Array.isArray(lesson) ? (lesson[1] ?? []) : []);

